import itemsData from '../data/items.json'

export type ItemCategory = 'materials' | 'basic' | 'consumables' | 'other'

export interface Item {
  id: string
  name: string
  rarity: number
  icon: string | null
  category: ItemCategory
  group: string
  usage: string | null
  description: string | null
  obtain: string | null
}

// Generated by scripts/items/gen-items.mjs — already sorted in in-game Depot order.
export const ITEMS = itemsData as Item[]

export const ITEM_CATEGORIES: { id: ItemCategory; label: string }[] = [
  { id: 'materials', label: 'Materials' },
  { id: 'basic', label: 'Basic Items' },
  { id: 'consumables', label: 'Consumables' },
  { id: 'other', label: 'Other' },
]

// Groups not listed here fall to the end in generator order.
const GROUP_ORDER: Record<ItemCategory, string[]> = {
  materials: ['Upgrade Materials', 'Chips', 'Battle Records', 'Module Materials', 'Personal Letters', 'Operator Tokens', 'Other Materials'],
  basic: ['Currency', 'Permits', 'Base Materials', 'Other'],
  consumables: ['Sanity Potions', 'Vouchers', 'Packs', 'Renaming Cards', 'Other'],
  other: ['Event Items', 'Collectibles', 'Misc'],
}

export function groupItems(items: Item[], category: ItemCategory) {
  const groups = new Map<string, Item[]>()
  for (const item of items) {
    if (!groups.has(item.group)) groups.set(item.group, [])
    groups.get(item.group)!.push(item)
  }
  const order = GROUP_ORDER[category]
  const rank = (group: string) => {
    const index = order.indexOf(group)
    return index === -1 ? order.length : index
  }
  return [...groups.entries()]
    .sort(([left], [right]) => rank(left) - rank(right))
    .map(([group, groupItems]) => ({ group, items: groupItems }))
}

